import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong();
        long total = 0, prev = nextLong();
        for (int i = 1; i < n; i++) {
            long cur = nextLong();
            total += cur > prev ? 1 : cur < prev ? 2 : 0;
            prev = cur;
        }
        System.out.println(total);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	prev := nextInt()
	total := 0
	for i := 1; i < n; i++ {
		cur := nextInt()
		if cur > prev {
			total++
		} else if cur < prev {
			total += 2
		}
		prev = cur
	}
	fmt.Println(total)
